module Server.Routes

open Fable.Core
open Thoth.Json
open Hedge.Workers
open Hedge.Router
open Codecs
open Server.Env

let dispatch (request: WorkerRequest) (env: Env) (ctx: ExecutionContext)
    : JS.Promise<WorkerResponse> option =
    let route = parseRoute request
    match route with
    | GET path when matchPath "/api/front" path = Some (Exact "/api/front") ->
        Some (Server.Handlers.getFront env)

    | GET path ->
        match matchPath "/api/search/:id" path with
        | Some (WithParam (_, id)) -> Some (Server.Handlers.search id env)
        | _ ->
        match matchPath "/api/article/:id" path with
        | Some (WithParam (_, id)) -> Some (Server.Handlers.getArticle id env)
        | _ ->
        match matchPath "/api/section/:id" path with
        | Some (WithParam (_, id)) -> Some (Server.Handlers.getSection id env)
        | _ ->
        None

    | _ -> None
